const inputText = $input.first().json.text;
const actionType = $input.first().json.subject;

// Si no hay texto, devuelve un objeto vacío.
if (!inputText) {
  return [{ json: {} }];
}

// Objeto para almacenar los datos extraídos.
const extractedData = {};

// Divide el texto en líneas.
const lines = inputText.split('\n');

// --- FUNCIÓN HELPER: Parseo de fecha con Zona Horaria (Reemplazo de Luxon) ---
function parseDateNative(dateString, timeZone) {
  // 1. NORMALIZACIÓN: Limpiamos el string para que JS nativo lo entienda.
  // Quita el día de la semana (ej: "Wednesday,")
  let clean = dateString.replace(/^[A-Za-z]+,\s*/, '');

  // Quita los conectores " de " del formato español (ej: "13 de August de 2025" -> "13 August 2025")
  clean = clean.replace(/\sde\s/g, ' ');

  // Arregla el formato con dos puntos en el año (ej: "2025:13:30" -> "2025 13:30")
  clean = clean.replace(/(\d{4}):(\d{1,2})/, '$1 $2');

  // 2. CREACIÓN BASE:
  // Creamos una fecha temporal. JS entenderá "August 13 2025 14:00" correctamente.
  const tempDate = new Date(clean);

  if (isNaN(tempDate.getTime())) return null;

  // 3. CÁLCULO DE ZONA HORARIA (La magia para reemplazar Luxon):
  // Creamos una fecha UTC con los mismos componentes numéricos que extrajimos del texto.
  const utcDate = new Date(Date.UTC(
    tempDate.getFullYear(), 
    tempDate.getMonth(), 
    tempDate.getDate(), 
    tempDate.getHours(), 
    tempDate.getMinutes(), 
    tempDate.getSeconds()
  ));

  // Usamos Intl para ver qué hora es REALMENTE en la zona horaria objetivo (timeZone)
  // cuando son las X horas en UTC.
  const zf = new Intl.DateTimeFormat('en-US', {
    timeZone: timeZone,
    year: 'numeric', month: 'numeric', day: 'numeric',
    hour: 'numeric', minute: 'numeric', second: 'numeric',
    hour12: false
  });

  // Descomponemos la fecha formateada en la zona destino
  const parts = zf.formatToParts(utcDate);
  const getPart = (type) => parseInt(parts.find(p => p.type === type).value, 10);

  const yearZ = getPart('year');
  const monthZ = getPart('month') - 1;
  const dayZ = getPart('day');
  const hourZ = getPart('hour') % 24; // Asegura formato 0-23
  const minZ = getPart('minute');

  // Reconstruimos la fecha desplazada
  const shiftedDate = new Date(Date.UTC(yearZ, monthZ, dayZ, hourZ, minZ));

  // Calculamos la diferencia (offset)
  const offset = shiftedDate.getTime() - utcDate.getTime();

  // Restamos el offset para obtener el momento absoluto correcto (ISO real)
  return new Date(utcDate.getTime() - offset).toISOString();
}
// ---------------------------------------------------------------------------

// Itera sobre cada línea del texto.
for (const line of lines) {
  let match;

  // Extracción de datos generales (Mismo Regex que tu código original)
  if ((match = line.match(/^First-name:\s*(.*)/))) {
    extractedData.nombre = match[1].trim();
    continue;
  }
  if ((match = line.match(/^Last-name:\s*(.*)/))) {
    extractedData.apellido = match[1].trim();
    continue;
  }
  if ((match = line.match(/^invitee-email:\s*(.*)/))) {
    extractedData.email = match[1].trim();
    continue;
  }
  if ((match = line.match(/^uuid:\s*(.*)/))) {
    extractedData.uuid = match[1].trim();
    continue;
  }
  if ((match = line.match(/^event-name:\s*(.*)/))) {
    extractedData.eventName = match[1].trim() || 'No especificado';
    continue;
  }
  if ((match = line.match(/^invitee-phone-number:\s*(.*)/))) {
    extractedData.telefono = match[1].trim() || 'No especificado';
    continue;
  }
  if ((match = line.match(/^Password:\s*(\S+)/))) {
    extractedData.zoomPassword = match[1].trim();
    continue;
  }
  if ((match = line.match(/^(https:\/\/\S*zoom\.us\/j\/\S+)/))) {
    extractedData.zoomLink = match[1].trim();
    continue;
  }

  // --- SECCIÓN DE FECHA ACTUALIZADA (SIN LUXON) ---
  const dateRegex = /^event-date:\s*(.*?)\s\((.*?)\)/;
  match = line.match(dateRegex);

  if (match) {
    const fechaParte = match[1].trim();
    const zonaHorariaParte = match[2].trim();

    try {
      const fechaIso = parseDateNative(fechaParte, zonaHorariaParte);

      if (fechaIso) {
        extractedData.fecha = fechaIso;
      } else {
        extractedData.fecha = `FALLÓ PARSEO: ${fechaParte} (Zona: ${zonaHorariaParte})`;
